#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Interval {
    pub min: i32,
    pub max: i32,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ChebyshevPoly {
    pub coef: Vec<i32>,
    pub domain: Interval,
    pub window: Interval,
}

pub fn chebyshev(coef: Vec<i8>) -> ChebyshevPoly {
    assert!(!coef.is_empty(), "coef must be non-empty");

    let coef_i32: Vec<i32> = coef.into_iter().map(|c| c as i32).collect();

    let domain = Interval { min: -1, max: 1 };
    let window = Interval { min: -1, max: 1 };

    debug_assert!(domain.min < domain.max);
    debug_assert!(window.min < window.max);

    ChebyshevPoly {
        coef: coef_i32,
        domain,
        window,
    }
}